"""Legacy EXPORT_ACCT fixed-width record formatter."""

from decimal import Decimal, ROUND_HALF_UP
from typing import Any


def _value(row: dict, key: str) -> Any:
    value = row.get(key, "")
    return "" if value is None else value


def _fixed(value: Any, width: int) -> str:
    text = str(value)
    return text[:width].ljust(width)


def _zpad_cents(value: Any, width: int) -> str:
    if value == "":
        value = 0

    cents = (Decimal(str(value)) * Decimal(100)).to_integral_value(
        rounding=ROUND_HALF_UP
    )
    return str(cents).zfill(width)


def format_account(row: dict) -> str:
    """Build one 77-character EXPORT_ACCT record without a terminator."""
    cred_hold = _value(row, "CRED_HOLD")
    if cred_hold == "":
        cred_hold = "N"

    create_dt = _value(row, "CREATE_DT")
    if create_dt == "":
        create_dt = "00000000"

    return (
        _fixed(_value(row, "ACCT_ID"), 10)
        + _fixed(_value(row, "ACCT_NM"), 40)
        + _fixed(_value(row, "REGION_CD"), 3)
        + _zpad_cents(_value(row, "ANN_REV"), 15)
        + str(cred_hold)
        + str(create_dt)
    )
